package com.exe201.rrms.repository; import com.exe201.rrms.entity.Payment; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface PaymentRepository extends JpaRepository<Payment,Long>{ Optional<Payment> findByCode(String code); List<Payment> findByUserIdOrderByCreatedAtDesc(Long userId); List<Payment> findByStatusOrderByCreatedAtDesc(String status); }